    'results/generalize/pythia14b_wiki_a100_s42/analysis',
]

for ad in checks:
    old = json.load(open(f'{ad}/5method_leadlag_pre_tyfix_batch.json'))
    new = json.load(open(f'{ad}/5method_leadlag.json'))

    print(f'\n=== {ad} ===')
    print(f'  Old top keys: {list(old.keys())[:5]}')
    print(f'  New top keys: {list(new.keys())[:5]}')

    # Handle old format: methods dict with ty_granger.pairs
    # Handle new format: pairs list with per-pair methods

    # Extract TY fwd/rev p-values from old format
    old_ty = {}
    if 'methods' in old and isinstance(old['methods'], dict) and 'ty_granger' in old['methods']:
        for p in old['methods']['ty_granger']['pairs']:
            old_ty[p['pair']] = (p.get('fwd_pvalue'), p.get('rev_pvalue'))

    # Extract from new format (pairs is a list, each pair has methods dict)
    new_ty = {}
    if 'pairs' in new:
        for p in new['pairs']:
            pname = p.get('pair', '')
            ty = p.get('methods', {}).get('ty_granger', {})
            new_ty[pname] = (ty.get('fwd_pvalue'), ty.get('rev_pvalue'))
    elif 'methods' in new and isinstance(new['methods'], dict) and 'ty_granger' in new['methods']:
        for p in new['methods']['ty_granger']['pairs']:
            new_ty[p['pair']] = (p.get('fwd_pvalue'), p.get('rev_pvalue'))

    if old_ty and new_ty:
        swaps = 0
        for pn in old_ty:
            if pn in new_ty:
                of, orr = old_ty[pn]
                nf, nr = new_ty[pn]
                if of is not None and nf is not None:
                    if abs(of - nr) < 1e-10 and abs(orr - nf) < 1e-10:
                        swaps += 1
        print(f'  TY fwd/rev swapped: {swaps}/{len(old_ty)}')
    else:
        print(f'  old_ty={len(old_ty)}, new_ty={len(new_ty)} - format mismatch')

    # Check PermG - extract from both formats
    old_pg_pvals = {}
    new_pg_pvals = {}

    if 'methods' in old and isinstance(old['methods'], dict) and 'perm_granger' in old['methods']:
        for p in old['methods']['perm_granger']['pairs']:
            old_pg_pvals[p['pair']] = p.get('fwd_pvalue')

    if 'pairs' in new:
        for p in new['pairs']:
            pg = p.get('methods', {}).get('perm_granger', {})
            new_pg_pvals[p['pair']] = pg.get('fwd_pvalue')
    elif 'methods' in new and isinstance(new['methods'], dict) and 'perm_granger' in new['methods']:
        for p in new['methods']['perm_granger']['pairs']:
            new_pg_pvals[p['pair']] = p.get('fwd_pvalue')

    if old_pg_pvals and new_pg_pvals:
        pg_match = all(abs((old_pg_pvals.get(k,0) or 0) - (new_pg_pvals.get(k,0) or 0)) < 0.01 for k in old_pg_pvals)
        print(f'  PermG approx unchanged: {pg_match}')

    # Summary comparison
    old_summary = old.get('summary', {})
    new_summary = new.get('summary', {})
    print(f'  K>=3: {old_summary.get("robust_pairs")} -> {new_summary.get("robust_pairs")}')
    print(f'  TY fwd sig: {old_summary.get("ty_forward_sig")} -> {new_summary.get("ty_forward_sig")}')
    print(f'  PermG fwd sig: {old_summary.get("perm_granger_fdr_forward_sig")} -> {new_summary.get("perm_granger_fdr_forward_sig")}')
PYEOF
